   "code": "// WebSocket client that survives restarts without a thundering herd\nfunction connect(url, onMessage, attempt = 0) {\n  const ws = new WebSocket(url);\n  ws.onopen = () => { attempt = 0; };\n  ws.onmessage = e => onMessage(JSON.parse(e.data));\n  ws.onclose = () => {\n    const cap = Math.min(30000, 500 * 2 ** attempt);          // 0.5 s, 1 s, 2 s ... max 30 s\n    setTimeout(() => connect(url, onMessage, attempt + 1), Math.random() * cap);\n  };\n  return ws;\n}",
