   "code": "// Express middleware for POST endpoints\nconst crypto = require('crypto');\napp.use(async (req, res, next) => {\n  const key = req.get('Idempotency-Key');\n  if (req.method !== 'POST' || !key) return next();\n  const hash = crypto.createHash('sha256').update(JSON.stringify(req.body)).digest('hex');\n  const inserted = await db.query(\n    `INSERT INTO idempotency_keys (key, request_hash, status) VALUES ($1, $2, 'started')\n     ON CONFLICT (key) DO NOTHING RETURNING key`, [key, hash]);\n  if (!inserted.length) {\n    const [row] = await db.query('SELECT * FROM idempotency_keys WHERE key = $1', [key]);\n    if (row.request_hash !== hash) return res.status(422).json({ error: { code: 'key_reused' } });\n    if (row.status !== 'done') return res.status(409).json({ error: { code: 'in_progress' } });\n    return res.status(row.response.status).json(row.response.body);   // replay the first answer\n  }\n  const json = res.json.bind(res);\n  res.json = body => {\n    db.query(`UPDATE idempotency_keys SET status='done', response=$2 WHERE key=$1`,\n      [key, { status: res.statusCode, body }]);\n    return json(body);\n  };\n  next();\n});",
